/* Illustrative role-based learning assignments; never treated as connected HR records. */
const learningPrograms=[
 {bu:'Production',roles:['Operator','Supervisor'],courses:['GMP Fundamentals','Equipment Operation','Batch Record Review']},
 {bu:'Quality',roles:['Lab Analyst','Quality Lead'],courses:['Data Integrity','Laboratory Safety','Deviation Investigation']},
 {bu:'Maintenance',roles:['Technician','Maintenance Lead'],courses:['Lockout / Tagout','Preventive Maintenance','Asset Reliability']},
 {bu:'Utilities',roles:['Utility Operator','Energy Engineer'],courses:['Utility Safety','Energy Monitoring','Resource Efficiency']}
];
let learningBU=0,learningRole=0,learningEmployee=-1;
function selectLearning(kind,value){if(kind==='bu'){learningBU=+value;learningRole=0;learningEmployee=-1}else if(kind==='role'){learningRole=+value;learningEmployee=-1}else learningEmployee=+value;render()}
function learningPeople(){const fi=state.factory<0?0:state.factory;const names=[['Omar Hassan','Mona Adel','Karim Ali'],['Nada Samir','Ahmed Tarek','Salma Mostafa'],['Hana Amin','Youssef Emad','Nour Salem'],['Ali Mahmoud','Farah Hany','Mariam Nabil']][(learningBU+fi)%4];return names.map((name,i)=>({name,scores:[38+i*3,47+i*3,56+i*3,65+i*3,74+i*3,82+i*3].map(v=>Math.min(100,v+learningBU*2+learningRole*3)),completed:[2,2,3][i]}))}
function roleLearningPanel(){const p=learningPrograms[learningBU],people=learningPeople(),chosen=learningEmployee<0?people:[people[learningEmployee]],scores=Array.from({length:6},(_,i)=>Math.round(chosen.reduce((s,e)=>s+e.scores[i],0)/chosen.length)),current=scores[5],complete=chosen.reduce((s,e)=>s+e.completed,0),required=chosen.length*3;
 const points=scores.map((v,i)=>[38+i*61,112-v*.85]);const path=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');
 return `<section class="panel workforce-learning role-learning"><div class="panelhead"><h2>Role-Based Learning</h2><button onclick="learningRequirements()">Course Plan ↗</button></div><div class="learning-filters"><select aria-label="Learning Business Unit" onchange="selectLearning('bu',this.value)">${learningPrograms.map((x,i)=>`<option value="${i}" ${i===learningBU?'selected':''}>${x.bu}</option>`).join('')}</select><select aria-label="Learning Position" onchange="selectLearning('role',this.value)">${p.roles.map((x,i)=>`<option value="${i}" ${i===learningRole?'selected':''}>${x}</option>`).join('')}</select><select aria-label="Learning Employee" onchange="selectLearning('employee',this.value)"><option value="-1">Role Average</option>${people.map((x,i)=>`<option value="${i}" ${i===learningEmployee?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="learning-status"><span><strong>${current}%</strong> Assessment Score</span><span><strong>${complete}/${required}</strong> Courses Complete</span><small>Illustrative · ${escapeHTML(scopeName())}</small></div><svg class="learning-curve" viewBox="0 0 370 140" role="img" aria-label="Assessment learning curve over six weeks">${[0,50,100].map(v=>`<line x1="38" x2="343" y1="${112-v*.85}" y2="${112-v*.85}" stroke="#b5eaff25"/><text x="29" y="${116-v*.85}" text-anchor="end">${v}</text>`).join('')}<line x1="38" x2="343" y1="44" y2="44" stroke="#ffd298" stroke-dasharray="4 4"/><text x="343" y="38" text-anchor="end" fill="#ffd298">Target 80%</text><path d="${path} L343,112 L38,112 Z" fill="#9ef9de15"/><path d="${path}" fill="none" stroke="#a4f8df" stroke-width="2.5"/>${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#a4f8df" ${vizAttrs('Learning Curve',(learningEmployee<0?'Role Average':people[learningEmployee].name)+' · Week '+(i+1),scores[i],'%',{extra:'Assessment score · Illustrative employee data'})}/><text x="${x}" y="131" text-anchor="middle">W${i+1}</text>`).join('')}</svg><small class="learning-course-summary">Required: ${escapeHTML(p.courses[0])} · ${escapeHTML(p.courses[learningRole+1])} · ${learningRole?'Team Leadership':'Safety Refresher'}</small></section>`}
function learningRequirements(){const p=learningPrograms[learningBU],people=learningPeople(),courses=[p.courses[0],p.courses[learningRole+1],learningRole?'Team Leadership':'Safety Refresher'];openModal(p.bu+' · '+p.roles[learningRole]+' Learning Plan',`<p>Required courses aligned with the selected position. Illustrative assignments · ${escapeHTML(scopeName())}.</p><table><thead><tr><th>Employee</th>${courses.map(x=>`<th>${x}</th>`).join('')}<th>Assessment</th></tr></thead><tbody>${people.filter((_,i)=>learningEmployee<0||i===learningEmployee).map(e=>`<tr><td>${e.name}</td>${courses.map((_,i)=>`<td>${i<e.completed?'✓ Completed':'In Progress · Due In 14 Days'}</td>`).join('')}<td>${e.scores[5]}%</td></tr>`).join('')}</tbody></table><p>Course completion and assessment scores are separate measures. Select an employee to view their six-week learning curve.</p>`)}
const workforceBeforeRoleLearning=workforceView;
workforceView=function(){return workforceBeforeRoleLearning().replace(/<section class="panel workforce-learning">[\s\S]*?<\/section>/,roleLearningPanel())};
